param([ValidateSet('build','test','throughput')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-coarse-interval-gdn-provider-20260916';$seed='D:\projects\AIMA-public-coarse-interval-gdn-20260916';$sha='4caedc84e34d45c92a78edfba6d6dacc1fdb9d5b';$bundle='D:\projects\coarse-interval-gdn-provider-4caedc8.bundle'
function Verify-File([string]$Path,[string]$Hash){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Hash){throw ('Changed input: '+$Path)}}
Verify-File $bundle '204ca7b8d323a8ed769821dc355f7f54bf29d7104fb655ffba863d1595b9671b'
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\coarse-interval-gdn-provider';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\interval_gdn_selftest.cpp';$exe=Join-Path $build 'coarse-interval-gdn-provider.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceFiles=@($source,(Join-Path $repo 'native\providers\sm121_attention_capacity.h'))
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName})
}
$sourceInputs=@($sourceFiles|Sort-Object -Unique|ForEach-Object {@{file=$_;sha256=(Get-FileHash $_ -Algorithm SHA256).Hash.ToLowerInvariant()}})
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; generated complete GDN WU, recurrent state and output components with the original SM121 exponential table';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$true;default_enabled=$false;purpose='Isolated complete GDN comparison of original scalar, original K16 intervals and C64 envelope variants. The C64 route sums four zero-C native BF16 signed and absolute products, then applies the unchanged coarse bound with its conditional2^-19 allowance and every original K16 loss. Only supported operand exponents80..174 or signed zero may admit. Outward endpoints must produce identical BF16 WU, both state residuals, or the final ordered output consumer. Original exact replay covers ambiguity and exceptions; the unrounded FP32 state update remains canonical. Preserve U=V ownership, checkpoints, residuals and raw output/state bits. Six lengths and four modes cover zero, finite, subnormal and eligibility endpoints. Full8192 uses one warmup and three rotated attempts across all four variants and both alias modes, with same-stream phase events resolved after completion. All outputs and buffers compare with the original algorithm and independent CPU columns. The fourth variant is the compiled product kernel without diagnostic counters and receives null statistics. Product dispatch has a default-off C64 option, but this component process does not load the model; no new GB10 or retained-performance acceptance.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=150
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $exe $meta.executable.sha256
 foreach($file in $meta.source_inputs){Verify-File $file.file $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
 $table='D:\projects\sm121-exp2-negative-f490940d.bin'
 Verify-File $table 'f490940df2bd80421159a96424c3e922330b7ca120d5ae7b629a973b9183730b'
 $spec.table=@{path=$table;bytes=(Get-Item $table).Length;sha256='f490940df2bd80421159a96424c3e922330b7ca120d5ae7b629a973b9183730b'}
 $spec.executable=$exe;$spec.arguments=@($table,$(if($Action -eq 'test'){'safety'}else{'throughput'}));$timeout=240
}
$out=Join-Path $repo ('build\coarse-interval-gdn-provider-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(2000,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $cases=@($reports|Where-Object {$_.kind -eq 'interval_gdn_component'})
 $expected=if($Action -eq 'test'){192}else{8};$measured=if($Action -eq 'test'){0}else{3}
 if($cases.Count -ne $expected){throw 'Incomplete interval GDN comparisons'}
 foreach($r in $cases){
  if($r.raw_bit_mismatches -ne 0 -or -not $r.all_attempts_verified -or -not $r.redzones_pass -or -not $r.immutable_nonaliased_inputs -or -not $r.intermediate_and_alias_ownership_checked -or $r.measured_attempts -ne $measured){throw 'Interval GDN numerical comparison failed'}
  if($Action -eq 'throughput' -and ($r.tokens -ne 8192 -or $r.samples_ms.Count -ne 3 -or $r.complete_preparation_wu_state_output_ms -le 0)){throw 'Incomplete full-shape timing'}
  if(-not $r.phase_events_same_stream -or $r.intermediate_host_synchronization -or $r.phase_events_enabled -ne ($Action -eq 'throughput')){throw 'Phase observation contract failed'}
  foreach($name in @('wu','state','output')){$phase=$r.phase_event_ms.$name;if($phase.samples.Count -ne 3 -or ($Action -eq 'throughput' -and $phase.median -le 0)){throw 'Incomplete phase timing'}}
  if($r.audit_enabled -ne ($r.variant -in @(1,2)) -or $r.null_statistics -ne ($r.variant -eq 3)){throw 'Audit specialization not exercised'}
  if($r.admissions.Count -ne 3 -or $r.considered.Count -ne 3 -or $r.matrix_interval -ne ($r.variant -gt 0) -or $r.coarse_interval -ne ($r.variant -ge 2) -or $r.interval_chunk -ne $(if($r.variant -ge 2){64}elseif($r.variant -eq 1){16}else{0})){throw 'Incomplete interval counters'}
  for($i=0;$i -lt 3;$i++){$expectedCount=if($r.variant -in @(1,2)){$r.tokens*4096*$(if($i -eq 0){2}else{1})}else{0};if($r.considered[$i] -ne $expectedCount -or $r.admissions[$i] -lt 0 -or $r.admissions[$i] -gt $expectedCount){throw 'Invalid interval count'}}
 }

}
